B.aou=new A.a(B.b,[5,94,"\ufc80\ufc81\ufc82\ufc83\ufc84\ufc85\n\ufc86\ufc87\ufc88\ufc89\ufc8a\ufc8b\ufc8c\ufc8d\ufc8e\n\ufc8f\ufc90\ufc91\ufc92\ufc93\ufc94\ufc95\ufc96\ufc97\ufc98","\u064a\u064e\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u064a\u064e\u0628\u06e1\u0644\u064f\u0648\u064e\u0646\u0651\u064e\u0643\u064f\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0628\u0650\u0634\u064e\u064a\u06e1\u0621\u0656 \u0645\u0651\u0650\u0646\u064e \u0671\u0644\u0635\u0651\u064e\u064a\u06e1\u062f\u0650 \u062a\u064e\u0646\u064e\u0627\u0644\u064f\u0647\u064f\u06e5\u0653 \u0623\u064e\u064a\u06e1\u062f\u0650\u064a\u0643\u064f\u0645\u06e1 \u0648\u064e\u0631\u0650\u0645\u064e\u0627\u062d\u064f\u0643\u064f\u0645\u06e1 \u0644\u0650\u064a\u064e\u0639\u06e1\u0644\u064e\u0645\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u064e\u0646 \u064a\u064e\u062e\u064e\u0627\u0641\u064f\u0647\u064f\u06e5 \u0628\u0650\u0671\u0644\u06e1\u063a\u064e\u064a\u06e1\u0628\u0650\u06da \u0641\u064e\u0645\u064e\u0646\u0650 \u0671\u0639\u06e1\u062a\u064e\u062f\u064e\u0649\u0670 \u0628\u064e\u0639\u06e1\u062f\u064e \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0641\u064e\u0644\u064e\u0647\u064f\u06e5 \u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0645\u065e","\u064a\u0627\u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 \u0644\u064a\u0628\u0644\u0648\u0646\u0643\u0645 \u0627\u0644\u0644\u0647 \u0628\u0634\u064a\u0621 \u0645\u0646 \u0627\u0644\u0635\u064a\u062f \u062a\u0646\u0627\u0644\u0647 \u0623\u064a\u062f\u064a\u0643\u0645 \u0648\u0631\u0645\u0627\u062d\u0643\u0645 \u0644\u064a\u0639\u0644\u0645 \u0627\u0644\u0644\u0647 \u0645\u0646 \u064a\u062e\u0627\u0641\u0647 \u0628\u0627\u0644\u063a\u064a\u0628 \u0641\u0645\u0646 \u0627\u0639\u062a\u062f\u0649 \u0628\u0639\u062f \u0630\u0644\u0643 \u0641\u0644\u0647 \u0639\u0630\u0627\u0628 \u0623\u0644\u064a\u0645"],t.M)
B.b_I=new A.a(B.b,[5,95,"\ufc99\n\ufc9a\ufc9b\ufc9c\ufc9d\ufc9e\ufc9f\ufca0\ufca1\ufca2\ufca3\n\ufca4\ufca5\ufca6\ufca7\ufca8\ufca9\ufcaa\ufcab\ufcac\ufcad\ufcae\n\ufcaf\ufcb0\ufcb1\ufcb2\ufcb3\ufcb4\ufcb5\ufcb6\ufcb7\n\ufcb8\ufcb9\ufcba\ufcbb\ufcbc\ufcbd\ufcbe\ufcbf\ufcc0\ufcc1\ufcc2\n\ufcc3\ufcc4\ufcc5\ufcc6\ufcc7\ufcc8\ufcc9\ufcca\ufccb\ufccc\ufccd\ufcce\ufccf","\u064a\u064e\u0670\u0653\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0671\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627\u0652 \u0644\u064e\u0627 \u062a\u064e\u0642\u06e1\u062a\u064f\u0644\u064f\u0648\u0627\u0652 \u0671\u0644\u0635\u0651\u064e\u064a\u06e1\u062f\u064e \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645\u06e1 \u062d\u064f\u0631\u064f\u0645\u065e\u06da \u0648\u064e\u0645\u064e\u0646 \u0642\u064e\u062a\u064e\u0644\u064e\u0647\u064f\u06e5 \u0645\u0650\u0646\u0643\u064f\u0645 \u0645\u0651\u064f\u062a\u064e\u0639\u064e\u0645\u0651\u0650\u062f\u0657\u0627 \u0641\u064e\u062c\u064e\u0632\u064e\u0627\u0653\u0621\u065e \u0645\u0651\u0650\u062b\u06e1\u0644\u064f \u0645\u064e\u0627 \u0642\u064e\u062a\u064e\u0644\u064e \u0645\u0650\u0646\u064e \u0671\u0644\u0646\u0651\u064e\u0639\u064e\u0645\u0650 \u064a\u064e\u062d\u06e1\u0643\u064f\u0645\u064f \u0628\u0650\u0647\u0650\u06e6 \u0630\u064e\u0648\u064e\u0627 \u0639\u064e\u062f\u06e1\u0644\u0656 \u0645\u0651\u0650\u0646\u0643\u064f\u0645\u06e1 \u0647\u064e\u062f\u06e1\u064a\u064e\u06e2\u0627 \u0628\u064e\u0670\u0644\u0650\u063a\u064e \u0671\u0644\u06e1\u0643\u064e\u0639\u06e1\u0628\u064e\u0629\u0650 \u0623\u064e\u0648\u06e1 \u0643\u064e\u0641\u0651\u064e\u0670\u0631\u064e\u0629\u065e \u0637\u064e\u0639\u064e\u0627\u0645\u064f \u0645\u064e\u0633\u064e\u0670\u0643\u0650\u064a\u0646\u064e \u0623\u064e\u0648\u06e1 \u0639\u064e\u062f\u06e1\u0644\u064f \u0630\u064e\u0670\u0644\u0650\u0643\u064e \u0635\u0650\u064a\u064e\u0627\u0645\u0657\u0627 \u0644\u0651\u0650\u064a\u064e\u0630\u064f\u0648\u0642\u064e \u0648\u064e\u0628\u064e\u0627\u0644\u064e \u0623\u064e\u0645\u06e1\u0631\u0650\u0647\u0650\u06e6\u06d7 \u0639\u064e\u0641\u064e\u0627 \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0645\u0651\u064e\u0627 \u0633\u064e\u0644\u064e\u0641\u064e\u06da \u0648\u064e\u0645\u064e\u0646\u06e1 \u0639\u064e\u0627\u062f\u064e \u0641\u064e\u064a\u064e\u0646\u062a\u064e\u0642\u0650\u0645\u064f \u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0645\u0650\u0646\u06e1\u0647\u064f\u06da \u0648\u064e\u0671\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0632\u0650\u064a\u0632\u065e \u0630\u064f\u0648 \u0671\u0646\u062a\u0650\u0642\u064e\u0627\u0645\u064d","\u064a\u0627\u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 \u0644\u0627 \u062a\u0642\u062a\u0644\u0648\u0627 \u0627\u0644\u0635\u064a\u062f \u0648\u0623\u0646\u062a\u0645 \u062d\u0631\u0645 \u0648\u0645\u0646 \u0642\u062a\u0644\u0647 \u0645\u0646\u0643\u0645 \u0645\u062a\u0639\u0645\u062f\u0627 \u0641\u062c\u0632\u0627\u0621 \u0645\u062b\u0644 \u0645\u0627 \u0642\u062a\u0644 \u0645\u0646 \u0627\u0644\u0646\u0639\u0645 \u064a\u062d\u0643\u0645 \u0628\u0647 \u0630\u0648\u0627 \u0639\u062f\u0644 \u0645\u0646\u0643\u0645 \u0647\u062f\u064a\u0627 \u0628\u0627\u0644\u063a \u0627\u0644\u0643\u0639\u0628\u0629 \u0623\u0648 \u0643\u0641\u0627\u0631\u0629 \u0637\u0639\u0627\u0645 \u0645\u0633\u0627\u0643\u064a\u0646 \u0623\u0648 \u0639\u062f\u0644 \u0630\u0644\u0643 \u0635\u064a\u0627\u0645\u0627 \u0644\u064a\u0630\u0648\u0642 \u0648\u0628\u0627\u0644 \u0623\u0645\u0631\u0647 \u0639\u0641\u0627 \u0627\u0644\u0644\u0647 \u0639\u0645\u0627 \u0633\u0644\u0641 \u0648\u0645\u0646 \u0639\u0627\u062f \u0641\u064a\u0646\u062a\u0642\u0645 \u0627\u0644\u0644\u0647 \u0645\u0646\u0647 \u0648\u0627\u0644\u0644\u0647 \u0639\u0632\u064a\u0632 \u0630\u0648 \u0627\u0646\u062a\u0642\u0627\u0645"],t.M)
